import React from 'react';

const PerformanceMetrics = ({ holdings, balance }) => {
    const totalValue = holdings.reduce((sum, item) => sum + item.current_value, 0);
    const totalInvested = holdings.reduce((sum, item) => sum + item.invested, 0);
    const totalPnl = totalValue - totalInvested;
    const pnlPercent = totalInvested > 0 ? (totalPnl / totalInvested) * 100 : 0;
    const netWorth = totalValue + balance;

    // Mock benchmark data (NIFTY 50)
    const benchmarkReturn = 12.5; // Mock 12.5% return
    const benchmarkValue = totalInvested * (1 + benchmarkReturn / 100);
    const benchmarkPnl = benchmarkValue - totalInvested;

    const metrics = [
        { label: 'Total Invested', value: `₹${totalInvested.toFixed(2)}`, color: '#8a9bb5' },
        { label: 'Current Value', value: `₹${totalValue.toFixed(2)}`, color: '#e0e6ed' },
        { label: 'Total P&L', value: `${totalPnl >= 0 ? '+' : ''}₹${totalPnl.toFixed(2)}`, color: totalPnl >= 0 ? '#4CAF50' : '#dc3545' },
        { label: 'P&L %', value: `${pnlPercent >= 0 ? '+' : ''}${pnlPercent.toFixed(2)}%`, color: pnlPercent >= 0 ? '#4CAF50' : '#dc3545' },
        { label: 'Net Worth', value: `₹${netWorth.toFixed(2)}`, color: '#e0e6ed' },
        { label: 'vs NIFTY 50', value: `${(pnlPercent - benchmarkReturn).toFixed(2)}%`, color: pnlPercent >= benchmarkReturn ? '#4CAF50' : '#dc3545' },
    ];

    return (
        <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))',
            gap: '12px',
            marginBottom: '20px'
        }}>
            {metrics.map((metric) => (
                <div key={metric.label} style={{
                    background: '#141b2b',
                    padding: '15px',
                    borderRadius: '10px',
                    border: '1px solid #2a3a5c',
                    textAlign: 'center'
                }}>
                    <div style={{ fontSize: '11px', color: '#8a9bb5' }}>{metric.label}</div>
                    <div style={{
                        fontSize: '18px',
                        fontWeight: 'bold',
                        color: metric.color,
                        marginTop: '4px'
                    }}>
                        {metric.value}
                    </div>
                </div>
            ))}
        </div>
    );
};

export default PerformanceMetrics;
